const outlines=['M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M4 4h16v16H4z M4 14h5l2 3h2l2-3h5','M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16','m15 4 5 5 M4 20l5-1L21 7l-5-5L4 14z','M4 14v-4 M8 18V6 M12 22V2 M16 18V6 M20 14v-4','M4 3v18h18 M8 16v-4 M13 16V8 M18 16V5','M3 3h18v18H3z m0 14 5-5 5 5 3-3 5 5 M15 7h.01','m3 10 14-6v16L3 14z M7 16l2 5h4l-2-4','m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z M12 7v6 M12 17h.01','M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'];
function refine(){document.querySelectorAll('.nav .ico').forEach((el,i)=>el.innerHTML=`<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${outlines[i]}"/></svg>`);const h=document.querySelector('.page-head h2');if(h)h.textContent='Overview';const p=document.querySelector('.page-head p');if(p)p.textContent='Your channels, conversations and team — in one place.';const queue=document.querySelector('.two .card h3');if(queue)queue.textContent='Needs attention';document.querySelectorAll('.network').forEach((x,i)=>{x.textContent=['f','◎','b','in','▶'][i]});document.querySelectorAll('.row .grow small').forEach(x=>x.textContent=x.textContent.replace('connected','demo accounts'));const details=document.querySelector('[data-page="admin"]');if(details){details.removeAttribute('data-page');details.onclick=()=>toast('All account health states are simulated. Production API capabilities remain unverified.')}const create=document.querySelector('[data-action="compose"]');if(create){create.removeAttribute('data-action');create.onclick=()=>toast('Composer design comes next. This review covers the Overview page.')}}
refine();
